/// One `user` row. Its JSON shows neither the password hash (only whether
/// it has one, `login`) nor the session secret.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct User {
    /// Unix ms.
    pub created_at: i64,
    /// Unix ms it was disabled: it, its keys and every session refused.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub disabled_at: Option<i64>,
    /// Its login, unique.
    pub email: String,
    /// A uuid v7.
    pub id: String,
    /// Unix ms; every session issued in its second or before is refused.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub invalidated_at: Option<i64>,
    /// The argon2id hash of its password; `None`: no dashboard login. In
    /// JSON, `login`: whether it has one.
    pub login: bool,
    /// Its name, as shown.
    pub name: String,
    /// The widest scopes it may issue, packed in JSON
    /// (`{"com.hashinbox": ["wallets:read"]}`).
    pub scopes: BTreeMap<String, Vec<String>>,
}

/// One `user_key` row. Its JSON shows neither the secret nor its hash.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct UserKey {
    /// Unix ms.
    pub created_at: i64,
    /// Unix ms it stops working; `None`: never.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expires_at: Option<i64>,
    /// `hip/…`: its public client id, a session's `kid` and `iss`.
    pub id: String,
    /// Unix ms; every session it issued in that second or before is
    /// refused (rotated).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub invalidated_at: Option<i64>,
    /// Unix ms it was last used; not kept yet.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_used_at: Option<i64>,
    /// What it is for: `shop backend`.
    pub name: String,
    /// Unix ms it was revoked: it and its sessions refused for good.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub revoked_at: Option<i64>,
    /// What it may do, covered by its user's; packed in JSON.
    pub scopes: BTreeMap<String, Vec<String>>,
    /// The user that issued it.
    pub user_id: String,
}

